from pathlib import Path
p=Path('src/SemesterPlanner.tsx')
s=p.read_text()
s=s.replace('BookOpen, Check, Info, Plus, Search, Undo2','Check, Plus, Search, Trash2, Undo2')
s=s.replace('  const [undo, setUndo] = useState<null | (() => void)>(null);','  const [undo, setUndo] = useState<null | (() => void)>(null);\n  const [dragged, setDragged] = useState<string | null>(null);')
s=s.replace('  const search = useRef<HTMLInputElement>(null);\n','')
s=s.replace('  const missing = (c: Course) => c.prerequisiteCourseIds.filter(id => !takenCourseIds.has(id));\n','')
s=s.replace('onClick={() => setSemester(n)}><span>Year', 'onClick={() => setSemester(n)} onDragOver={e => { if (dragged) e.preventDefault(); }} onDrop={e => { e.preventDefault(); const course = courseById.get(e.dataTransfer.getData("text/plain")); if (course) change(course, n); setDragged(null); }}><span>Year')
s=s.replace('<button key={c.id} className="sp-selection-course" onClick={() => setSelected(c)}><span><strong>{c.code}</strong>{c.title}</span><small>{c.units} units <ArrowUpRight size={13}/></small></button>', '<div key={c.id} className="sp-selection-item" draggable onDragStart={e => { e.dataTransfer.setData("text/plain", c.id); setDragged(c.id); }} onDragEnd={() => setDragged(null)}><button className="sp-selection-course" onClick={() => setSelected(c)}><span><strong>{c.code}</strong>{c.title}</span><small>{c.units} units <ArrowUpRight size={13}/></small></button><button className="sp-selection-remove" aria-label={`Remove ${c.code} from plan`} onClick={() => remove(c)}><Trash2 size={14}/></button></div>')
s=s.replace(' ref={search}', '')
s=s.replace('{query ? "No matching courses" : "All suggested courses are in your plan."}', '{query ? "No matching courses" : !remaining.length ? "Every catalog course is in your plan." : "All suggested courses are in your plan."}')
s=s.replace('{query ? "Try another course code or name." : "Browse all courses for more options."}', '{query ? "Try another course code or name." : !remaining.length ? "Select a semester above to review or adjust courses." : "Browse all courses for more options."}')
s=s.replace('<button onClick={() => { setQuery(""); setFilter("all"); }}>Browse all courses <ArrowRight size={14}/></button>', '{remaining.length > 0 && <button onClick={() => { setQuery(""); setFilter("all"); }}>Browse all courses <ArrowRight size={14}/></button>}')
s=s.replace('import { useEffect, useRef, useState }','import { useEffect, useState }')
p.write_text(s)
